    "difficulty": 3,
    "question": "次の英文は、多数決に関する記述の一部である（一部省略又は変更している箇所がある。）。A、Bに当てはまるものの組合せとして最も妥当なのはどれか。なお、文中の［伏字］については設問の都合上伏せてある。\n\nThe more mechanistic approach to social choice aspires for individuals’ preferences to be aggregated impartially into some determinate collective choice. But, as has long been known, majority rule may well be indeterminate. The structure of people’s preferences may be such that any option can beat any other option by a majority vote. Where we stop — what we settle upon as ‘the’ democratic outcome — is then highly arbitrary.\n\nImagine the simplest three-voter, three-issue case, with preferences distributed as follows:\n\nAlan prefers option Z to Y to X;\nBea prefers option X to Z to Y;\nCharlie prefers option Y to X to Z.\n\nThen majority rule leads us around in circles. Option Y beats X (by the votes of ［伏字］ and ［伏字］), option Z beats Y (by the votes of ［A］ and ［伏字］) but option X beats Z (by the votes of ［A］ and ［伏字］). In cases such as this, majority voting yields no determinate answer to the question of which option is socially preferred.\n\n［B］ noticed this danger over two centuries ago. A vast literature has since grown up in and around mathematical economics trying — largely unsuccessfully — to find a way out of the general impossibility result that Arrow constructed upon those foundations.",
