    "difficulty": 3,
    "question": "次の英文は、政治学の方法論に関する文献の一部である（一部省略又は変更している箇所がある。）。A、B、Cに当てはまるものの組合せとして最も妥当なのはどれか。ただし、単数形と複数形の区別はしないものとする。なお、文中の［伏字］については設問の都合上伏せてある。\n\nWhich method—large-n or case study—is better? We should favor the method that allows the most strong tests. More tests are better than fewer; strong tests are better than weak; many strong tests are best, as are methods that allow them. The structure of available data decides which method is strongest for testing a given theory.\n\nMost theories of war are best tested by ［A］ methods because the international historical record of prewar politics and diplomacy, which serves as our data, usually lends itself better to deep study of ［B］ cases. A few cases are recorded in great depth (the two World Wars) but the historical record deteriorates sharply as we move beyond the fifteenth or twentieth case. As a result ［A］ often allow more and stronger tests than ［伏字］ methods. Conversely, ［C］ methods are relatively more effective for testing theories of American electoral politics because very large numbers of cases (of elections, or of interviewed voters) are well recorded. Case studies can be strong tools for exploring American politics, however, especially if in-depth case studies yield important data that is otherwise inaccessible, and ［C］ analysis can be a strong method for exploring international politics if relevant test data is recorded for many cases.",
