    "question": "次の英文は、ある国際関係理論について説明した文章の一部である（一部省略又は変更している箇所がある。）。A、B、Cに当てはまるものの組合せとして最も妥当なのはどれか。\n\nThe core of A. Wendt’s argument is the rejection of the neorealist position, according to which anarchy must necessarily lead to self-help. Whether it does or not cannot be decided a priori; it depends on the ［A］ between states. In these processes of ［A］, the ［B］ of states are created. For neorealists, ［B］ are a given; states know who they are and what they want before they begin ［A］ with other states. For Wendt, it is such an ［A］ that creates and instantiates one structure of ［B］ rather than another; structure has no existence or causal powers apart from process. States want to survive and be secure; neorealists and constructivists agree about that. But what kind of security policy follows from this? Do states seek to become as powerful as possible or are they content with what they have? Wendt argues that we can only find out by studying ［B］ as they are shaped in the ［A］ between states.\n\n（中略）\n\nWendt drives home the point that constructivism is not merely about adding the role of ［C］ to existing theories of International Relations. Material power and state interest are fundamentally formed by ［C］ and social ［A］. Therefore, states in an anarchic system may each possess military and other capabilities which can be seen as potentially threatening by other states; but enmity and arms races are not inevitable outcomes. Social ［A］ between states can also lead to more benign and friendly cultures of anarchy.",
