    "question": "次のア、イ、ウの英文は、官僚の行動についての理論を説明した文章の一部である（一部変更している箇所がある。）。それぞれの文章と、そこで説明されている理論の提唱者の組合せとして最も妥当なのはどれか。\n\nア. In the bureau-shaping model rational senior bureaucrats do not value routine, conflictual work in large organizations staffed mainly by non-élite personnel, exposed to public criticism and risks from mistakes and situated a long way from political power centres. Instead, they value individually innovative work with a developmental rhythm, a broad scope of concerns, low exposure to public criticism, collegial and élite work units, restricted hierarchy, congenial personal relations, high-status organizational and social contacts especially professional ones, and proximity to political power centres.\nイ. Bureaucratic officials (and all other social agents) seek to attain their goals rationally. In other words, they act in the most efficient manner possible given their limited capabilities and the cost of information. Hence all the agents in our theory are utility maximizers. In practical terms, this implies that whenever the cost of attaining any given goal rises in terms of time, effort, or money, they seek to attain less of that goal, other things being equal. Conversely, whenever the cost of attaining a goal falls, they seek to attain more of it.\nウ. A bureaucrat who may not be personally motivated to maximize the budget of his bureau is usually driven by conditions both internal and external to the bureau to do just that. One should not be surprised, therefore (as I was initially), to hear the most dedicated bureaucrats describe their objective as maximizing the budget for the particulars service(s) for which they are responsible. Some people resist accepting this rationality argument for budget maximization by bureaucrats because this behavioral assumption is not clearly consistent with higher-level goals.",
