      "ウ": "国家責任条文は、対抗措置を有責国に義務の履行を促すための手段とし、可能な限り履行を再開できる方法を求める。国際司法裁判所も、国際社会全体に対する義務の保護について、すべての国に法的利害関係があると述べた。",
