    "question": "国際安全保障に関するア～エの記述のうち、妥当なもののみを全て挙げているのはどれか。\n\nア. Because United Nations peacekeeping operations are binding measures that are undertaken only when the Security Council determines the existence of a threat to the peace, they do not require the consent of the host state or other parties to the conflict prior to their deployment, and the use of armed force in the host state is generally authorized.\nイ. The Security Council of the United Nations may, even if it does not determine that a threat to the peace exists, recommend appropriate procedures or methods of adjustment at any stage of a dispute between UN member states, if it finds that the continuance of the dispute is likely to endanger the maintenance of international peace and security.\nウ. In the Oil Platforms case＊1, the International Court of Justice held that in order for a UN member state to exercise its right of self-defense, it must not only fulfill the requirements set forth in the UN Charter, but also comply with the requirements of customary international law regarding the exercise of the right of self-defense, such as necessity and proportionality.\nエ. The Outer Space Treaty＊2 not only makes the claim of sovereignty over outer space illegal, but also establishes the principle of peaceful use of outer space, explicitly prohibiting parties from conducting military activities such as the establishment of military bases or the deployment of conventional weapons in any outer space.\n\n（注）＊1 Oil Platforms case: International Court of Justice, Oil Platforms (Islamic Republic of Iran v. United States of America), Judgment of 6 November 2003\n＊2 Outer Space Treaty: Treaty on Principles Governing the Activities of States in the Exploration and Use of Outer Space, including the Moon and Other Celestial Bodies, adopted on 19 December 1966",
