    "question": "次の文章は、あるよく知られた哲学者の著作の一節である。この文章の筆者の道徳論（倫理学）に関する記述として最も妥当なのはどれか。\n\nわれわれが無制限に善とみとめうるものとしては、この世界の内にもまた外にも、ただ善なる意志しか考えられない。理解力や機知や判断力やその他いろいろに呼ばれるところの精神の才能、および勇気や果断や根気強さなどという、気質のもつ特質は、確かに多くの点で善なるものであり望ましいものである。しかしそれらは、またきわめて悪いもの有害なものにもなりうる。すなわち、それら自然の賜物を使用する任務をもつ意志――したがって意志の固有の性質は（才能や気質と区別して）性格と呼ばれる――が、善でない場合である。",
