      "イ": "トーマス・マンはドイツのリューベックで生まれた。マンの小説の多くは芸術とそれに対立する現実的生活との関係を扱い、『ブデンブローク家の人々』では、四世代の間に旺盛な生への意欲を失い、死の要素をはらんだ精神・芸術の世界へ移行する一家の歴史を語った。『ヴェニスに死す』では、美少年に魅惑される作家を描き出し、『魔の山』では、スイスのサナトリウムでの一人の青年の内的発展を通してヨーロッパの運命に向き合った。",
