      "エ": "フランツ・カフカはプラハで生まれた。父親はドイツ系ユダヤ人の音楽家であったが、カフカ自身は、公務員として勤務しつつ世界一般と自分自身の間の関係を終生問い続けた。『変身』では、鳥になった男グレゴール・ザムザと彼の家庭の日常を、変身の由来の説明なしに冷静に語った。罪を犯してもいないのに逮捕された銀行員の自己証明の物語『審判』の後は、神話の現在化を目指した四部作『ヨセフとその兄弟たち』によってナチスへの抗議を試みた。",
      "オ": "ギュンター・グラスはドイツのカルフで生まれた。『車輪の下』には、退学することになった神学校での苦い経験が色濃く反映されている。第一次世界大戦がもたらしたヨーロッパ世界の崩壊に衝撃を受け、戦後に発表した『デーミアン』では、ヨーロッパそのものと同様に解体した自らの生活と思想の再建を試みた。『ブリキの太鼓』は、国民的遊戯の名人の伝記と遺稿の詩に加えて履歴書を編集する形式で現代批判を行った最後の長編小説である。"
