    "question": "次の図1、図2は製造業5業種（化学、機械、金属、食料品、繊維）＊について、工業出荷額全体に占める割合を示したものである。図1は日本の1965年～2015年の10年ごとの変化、図2は2019年の韓国、ニュージーランド、バングラデシュ、ロシアの4か国の状況について示している。A～Eに当てはまる5業種の組合せとして最も妥当なのはどれか。\n\n＊ 図1の日本の5業種には、以下の中分類の業種（1993年改訂の日本標準産業分類に基づく）をそれぞれ含む。",
