      "ウ": "Bは調査者と当事者が問題の解決を図り、行動の過程を検討するアクション・リサーチを説明している。Cは個人の生活や経験を社会の変化に結び付けるライフヒストリー研究に当たる。",
      "エ": "Bは参加者と協働する実践的な研究方法として妥当である。Dと異なり、質的調査では参加者の同意や秘密の保持に配慮し、公表で匿名化する場合がある。",
      "オ": "Cは『口述の生活史』という具体例も含めて妥当である。Dのように実名での公表を必須にし、公表後にだけ知らせる一律の倫理規則はない。"
