      "イ": "死に関わる意思決定は、患者本人だけでなく家族にも深く関わる問題であるため、1990年代に開催された日本学術会議における「死と医療特別委員会報告」では、患者本人の意思が不明であるときは、家族の判断によって、延命治療の手控えや中止を認めるべきであるとされている。現在の日本では、本人の望む終末期の医療やケアについて、家族や医療従事者らと前もって話合いを重ねる「アドバンス・ディレクティブ」の普及が図られている。",
