      "エ": "遊牧国家としてのウイグルが滅亡すると、ウイグル人は天山山脈東部に移住し、10世紀にイスラーム教を受容した。彼らの移住と改宗を契機として、トルコ系遊牧部族のイスラーム化と西アジア進出が始まり、そうした部族の一つが建てたサーマーン朝は11世紀にバグダードに入城してイランからシリアまでの西アジア各地を支配した。トルコ系遊牧民の西進は、さらにアナトリア半島にも及び、その延長線上に現代のトルコ共和国がある。",
