    "question": "次は、学齢期の子どもの学力に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n学力とは、狭義には、学校教育の中で教授される知識や技能を子どもがどれだけ身に付けているかを意味し、学力テストを用いて測定される。日本の学齢期の子どもの学力をめぐる問題の一つとして、学習内容の抽象化と認知発達の個人差などのため、学校での学習についていけない子どもが目立ち始める、［A］という現象が知られている。こうした現象は最初、聴覚障害児に対する教育上の問題として提起されたが、後に広く子どもの学力全般の問題を指して［A］という用語が用いられるようになった。また、複数の国際的な学力調査の結果から、藤村宜之（2012）において、日本の学齢期の子どもの学力では、「［B］」に対して、「［C］」が相対的に低い傾向がみられることも指摘された。\n学齢期の子どもの学力に関連する要因の一つとして、［D］が挙げられる。［D］は情報の保持と処理を同時に行う認知能力で、児童期を通じて発達する。これが十分に機能しないと、学校での学びに様々な面で困難を来すことが指摘されている。ただし、S. E. ギャザコールとT. P. アロウェイ（2008）によると、［D］の個人差は大きく、7歳児の上位10％は［E］児の平均とおよそ一致する一方で、下位10％は4歳児の平均を下回ることが報告されている。",
