    "difficulty": 3,
    "question": "A. シュッツの理論に関する記述ア～エのうち、妥当なもののみを挙げているのはどれか。\n\nア．M. モースの理解社会学を理論的に発展させるために、現象学の方法を社会学に適用した。モースが、社会的行為を、行為者が付与する客観的意味に着目して理解し説明することが社会学であると定義したところ、A. シュッツは、このようなモースの行為や意味といった基礎概念を、主として現象学の方法を援用しながら厳密化することを試みた。\n\nイ．T. パーソンズの理論における「主観的現象」の扱いについて批判した。パーソンズが、行為者の動機という主観的現象を、規範的価値という観察者による客観的な解釈図式で説明したのに対し、A. シュッツは、規範的価値もまた主観的観点と関係しており、行為者の動機を観察者の観点からではなく行為者自身の観点から明らかにしていくことの重要性を主張した。\n\nウ．社会の中で生活している行為者が経験している世界を「多元的現実」と捉えて考察した。行為者が日常生活世界で経験している現実は、唯一の現実というわけではなく、夢の世界、空想の世界、宗教的体験の世界、科学的思考の世界などの限定的な意味領域があり、それらに現実のアクセントが付与されることによって、現実として経験されるとした。\n\nエ．社会学者が常識的な概念を用いて二次的に現実を再構成する以前に、行為者が日常生活世界において、科学的な概念を用いて一次的に構成している現実を、行為者自身の視点から記述しようとした。こうした「現象学的社会学」の観点は、世界観の全体をその人が拠って立つ集団との関連で捉えるK. マンハイムの「想像の共同体」の概念に引き継がれていった。",
