      "ウ": "E. デュルケムは、近代社会における社会的分業がもたらす社会の分化と社会圏の交錯によって、個人の個性に対する抑圧と「自由のない平等」によって特徴付けられる質的個人主義が誕生するものの、そのことがかえって、人格の尊厳や道徳的個人主義といった伝統社会に存在した宗教的規範を弱める結果を招くとした。その上で、弱まった規範を回復するためには、氏族に対する崇拝に代わる動物崇拝としてのトーテミズムが重要であると主張した。",
